{
  "hypotheses": [
    {
      "stance": "bull",
      "mechanism": "FY2024 Q4 Entertainment DTC 廣告收入年增 14%。若這股成長延續，且新增廣告收入高於相關增量成本，相較廣告收入持平的情境，Disney 可在訂戶成長放緩時仍提高串流營業利益。管理層預期 FY2025 營業利益年增約 8.75 億美元，但廣告對增額的貢獻尚未量化。",
      "target": "Disney",
      "horizon": "2025-12-31",
      "catalyst": "2024-11-14 財報同時揭露廣告成長實績與 FY2025 Q1 Disney+ Core 訂戶季減預期。先看 Disney 的 Q1 財報是否顯示廣告收入續增，再以全年財報核對獲利。",
      "prediction": "截至 2025-12-31，預期 Disney 的 FY2025 Q1 財報顯示 Entertainment DTC 廣告收入較上年同期增加，且全年財報顯示 FY2025 Entertainment DTC 營業利益高於 FY2024。後者是獲利結果，廣告貢獻仍須另行歸因。",
      "invalidation": "同一截止日前，若 Disney 揭露 FY2025 Q1 Entertainment DTC 廣告收入較上年同期持平或下降，廣告續增假設即失效。若廣告續增，但 FY2025 全年同口徑營業利益較 FY2024 持平或下降，則獲利預測失效。未揭露廣告增幅時，該環節仍待驗證。",
      "claim_ids": ["fact:dis-fy24:streaming", "fact:dis-fy24:fy25"]
    },
    {
      "stance": "bear",
      "mechanism": "FY2024 Q4 Experiences 營業利益年減 6%，而 FY2025 指引將主要成長寄望於下半財年。若獲利回升較指引假設晚一季，部分改善可能遞延至 FY2026，使 FY2025 部門營業利益增幅低於指引下緣。延遲屬情境假設，財報未量化單季遞延的金額。",
      "target": "Disney",
      "horizon": "2025-12-31",
      "catalyst": "2024-11-14 發布的 Experiences 指引預期 FY2025 營業利益年增 6% 至 8%，成長偏向下半年。FY2025 Q3 是下半財年首季，可先從 Disney 季報觀察回升時點。",
      "prediction": "截至 2025-12-31，預期 Disney 財報顯示 FY2025 Q3 Experiences 營業利益較上年同期持平或下降，且 FY2025 全年部門營業利益較 FY2024 增幅低於 6%。",
      "invalidation": "同一截止日前，若 Disney 揭露 FY2025 Q3 Experiences 營業利益高於上年同期，則推翻該季尚未恢復年增的預測。若 FY2025 全年同部門營業利益較 FY2024 年增至少 6%，則推翻全年低於指引下緣的預測。",
      "claim_ids": ["fact:dis-fy24:experiences"]
    }
  ],
  "assessment": {
    "thesis": "Disney 的 FY2025 獲利改善有兩個觀察重點，分別是串流廣告成長能否帶動 Entertainment DTC 增利，以及 Experiences 能否在下半財年及時恢復成長。",
    "key_gap": "Entertainment DTC 預期年增約 8.75 億美元的營業利益中，多少來自廣告業務本身，多少反映 FY2024 印度 DTC 約 2 億美元的負面基期影響？",
    "next_check": "先查 Disney 於 FY2025 Q1 結束後發布的季度財報，核對 Entertainment DTC 廣告收入年增方向及 Disney+ Core 付費訂戶季變動。至 2025-12-31 以全年財報核對同口徑營業利益增額。部門結果可公開驗證，精確歸因則需公司揭露獲利變動明細，否則須取得非公開成本及收入資料。",
    "evidence_limits": [
      {
        "evidence_id": "dis-fy24:streaming",
        "limit": "FY2024 Q4 廣告收入年增 14%，Entertainment DTC 營業利益為 2.53 億美元。合併 DTC 的 3.21 億美元涵蓋範圍較廣，兩者均未拆出廣告獲利。"
      },
      {
        "evidence_id": "dis-fy24:fy25",
        "limit": "全年增利約 8.75 億美元與 Q1 Core 訂戶季減均屬管理層預期。印度 DTC 約 2 億美元為基期負面影響，實際年度增利仍待揭露。"
      },
      {
        "evidence_id": "dis-fy24:experiences",
        "limit": "FY2024 Q4 營業利益 17 億美元、年減 6% 為實績。FY2025 年增 6% 至 8% 且偏重下半年為指引，未提供逐季回升幅度。"
      }
    ],
    "public_checks": [
      {
        "metric": "Entertainment DTC 廣告收入年增方向",
        "source_to_watch": "Disney 投資人關係季度財報的 Entertainment DTC 營運說明",
        "window": "FY2025 Q1 結束後的首份季報，與 FY2024 Q1 比較",
        "impact_on_thesis": "續增支持廣告成長延續，持平或下滑則削弱多方假設。廣告收入是獲利貢獻的代理指標，無法辨識增量成本。",
        "evidence_ids": ["dis-fy24:streaming"]
      },
      {
        "metric": "Disney+ Core 季末付費訂戶季變動",
        "source_to_watch": "Disney 季度財報的串流付費訂戶數",
        "window": "FY2025 Q1 季末與 FY2024 Q4 季末比較，於 Q1 財報核對",
        "impact_on_thesis": "若較上季逾 1.2 億的基期減少，符合管理層預期，也使廣告能否抵銷訂閱端壓力更值得追蹤。訂戶數衡量採用情況，無法直接換算當季認列收入。",
        "evidence_ids": ["dis-fy24:streaming", "dis-fy24:fy25"]
      },
      {
        "metric": "Experiences 單季營業利益年增方向",
        "source_to_watch": "Disney 季度財報的 Experiences 部門營業利益",
        "window": "FY2025 Q3 結束後的季報，與 FY2024 Q3 比較",
        "impact_on_thesis": "下半財年首季仍持平或衰退，表示達到全年增長下緣更仰賴 Q4。若 Q3 已恢復年增，則降低回升延遲的可信度。",
        "evidence_ids": ["dis-fy24:experiences"]
      }
    ],
    "supply_chain": [],
    "trade_opportunities": []
  }
}
